typedef Activity=({String label,String icon,String hint,String stat,int delta,int fatigue,int coins});
const defaultActivities=<Activity>[(label:'별 관측',icon:'✦',hint:'지혜 +3 · 피로 +1',stat:'지혜',delta:3,fatigue:1,coins:0),(label:'정원 돌보기',icon:'❈',hint:'공감 +3 · 피로 +1',stat:'공감',delta:3,fatigue:1,coins:0),(label:'공방 돕기',icon:'◈',hint:'용기 +2 · 은화 +4',stat:'용기',delta:2,fatigue:1,coins:4),(label:'달빛 아래 휴식',icon:'☾',hint:'피로 -2 · 성장 없음',stat:'지혜',delta:0,fatigue:-2,coins:0),(label:'장터 심부름',icon:'◇',hint:'은화 +6 · 피로 +1',stat:'공감',delta:0,fatigue:1,coins:6)];
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();final s=jsonDecode(await rootBundle.loadString('story/story.json'));final locales=<String,Map<String,String>>{};for(final locale in ['ko','en']){final raw=jsonDecode(await rootBundle.loadString('story/locales/$locale.json')) as Map;locales[locale]=raw.map((key,value)=>MapEntry('$key','$value'));}runApp(Game(s,locales:locales));}
class Game extends StatefulWidget{const Game(this.story,{this.locales=const {},super.key});final Map<String,dynamic>story;final Map<String,Map<String,String>>locales;@override State<Game> createState()=>_Game();}
class _Game extends State<Game>{int week=1,coins=12,fatigue=0,selected=0,page=0,persona=0,eventIndex=0;String locale='ko';bool finished=false;final history=<String>[];final stats={'지혜':4,'공감':5,'용기':3},bonds={'lumi':0,'bora':0,'taro':0};final milestones=<String,bool>{};final collectionEntries=<Map<String,dynamic>>[];String lastResult='',lastLine='';ui.Image? image,personaImage;late GameSession session;late CollectionPort collection;
LocaleCatalog get catalog=>LocaleCatalog(widget.locales);
String tr(String key,String fallback)=>catalog.text(locale,key,fallback:fallback);
void toggleLocale()=>setState((){locale=locale=='ko'?'en':'ko';setActiveLocale(locale,catalog);});
List<Activity> get activities {final raw=widget.story['activities'] as List?;if(raw==null||raw.isEmpty)return defaultActivities;return raw.map((e){final a=e as Map;return(label:'${a['label']}',icon:'${a['icon']}',hint:'${a['hint']}',stat:'${a['stat']}',delta:(a['delta'] as int?)??0,fatigue:(a['fatigue'] as int?)??0,coins:(a['coins'] as int?)??0);}).toList();}
@override void initState(){super.initState();collection=createCollectionAdapter();collectionEntries.addAll(collection.read());session=GameSession(JsonStoryAdapter(widget.story),createSaveAdapter());try{final restored=session.restore();if(restored!=null)page=restored.page;}catch(_){ }sync();FontLoader('NotoSansKR')..addFont(rootBundle.load('assets/fonts/NotoSansKR-Regular.ttf'))..load().then((_){if(mounted)setState((){});});rootBundle.load('assets/noa-sprite-sheet.png').then((b)=>ui.instantiateImageCodec(b.buffer.asUint8List())).then((c)=>c.getNextFrame()).then((f){if(mounted)setState(()=>image=f.image);});rootBundle.load('assets/lumen-personality-sheet.png').then((b)=>ui.instantiateImageCodec(b.buffer.asUint8List())).then((c)=>c.getNextFrame()).then((f){if(mounted)setState(()=>personaImage=f.image);});}
void sync(){setActiveLocale(locale,catalog);final s=session.snapshot(page:page);week=s.week;coins=s.coins;fatigue=s.fatigue;selected=s.selected;persona=s.persona;eventIndex=s.eventIndex;lastResult=s.lastResult;lastLine=s.lastLine;history..clear()..addAll(s.history);stats..clear()..addAll(s.stats);bonds..clear()..addAll(s.bonds);milestones..clear()..addAll(s.milestones);}
void next(){final a=activities[selected.clamp(0,activities.length-1)];setState((){session.choose(ActivityChosen(a.stat,a.delta,a.coins,a.fatigue,label:a.label));sync();if(week>=session.story.endingWeek){finished=true;recordEnding();page=2;}else{final upcoming=session.story.events.indexWhere((e)=>e['week']==week);if(upcoming>=0){eventIndex=upcoming;session.world.progress[0]!.eventIndex=eventIndex;page=3;}}session.persist(page:page);});}
void recordEnding(){final d=resolveEnding(JsonStoryAdapter(widget.story),stats,bonds:bonds,milestones:milestones);collection.record('${d['id']}',(d['rank'] as int?)??1);collectionEntries..clear()..addAll(collection.read());}
bool choiceAvailable(Map e)=>e['requiresStat']==null||(stats[e['requiresStat']]??0)>=(e['requiresMin'] as int? ?? 0);
void chooseEvent(int i){final e=session.story.events[eventIndex]['choices'][i];if(!choiceAvailable(e)){setState(()=>lastResult='조건 부족 · ${e['requiresStat']} ${e['requiresMin']} 필요');return;}final d=e['delta'] as int,g=e['coins'] as int;setState((){session.chooseEvent(StoryChoiceMade(e['stat'],d,g,e['label'],bondId:e['bondId'] as String?,bondDelta:(e['bondDelta'] as int?)??0,rivalId:e['rivalId'] as String?,rivalDelta:(e['rivalDelta'] as int?)??0,requiresStat:e['requiresStat'] as String?,requiresMin:(e['requiresMin'] as int?)??0,line:e['line'] as String? ?? ''));sync();page=0;session.persist(page:page);});}
GameSnapshot snapshot()=>session.snapshot(page:page);
void restore(GameSnapshot s){setState((){session.world.restore(s);sync();page=s.page;});}
void select(int i){setState((){selected=i;session.world.progress[0]!.selected=i;session.persist();});}
Future<void> importSave()async{final c=TextEditingController();final raw=await showDialog<String>(context:context,builder:(_)=>AlertDialog(title:const Text('저장 코드 붙여넣기'),content:TextField(controller:c,maxLines:5),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('취소')),FilledButton(onPressed:()=>Navigator.pop(context,c.text),child:const Text('복원'))]));if(raw==null||raw.isEmpty)return;try{restore(GameSnapshot.decode(raw));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('저장 코드가 올바르지 않습니다.')));}}
void restart(){session.save.clear();setState((){session=GameSession(JsonStoryAdapter(widget.story),createSaveAdapter());week=1;coins=12;fatigue=0;selected=0;page=0;eventIndex=0;finished=false;lastResult='';lastLine='';history.clear();stats..updateAll((k,v)=>k=='지혜'?4:k=='공감'?5:3);bonds..updateAll((k,v)=>0);milestones.clear();});}
@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:Scaffold(backgroundColor:paper,body:SafeArea(child:GestureDetector(onTapUp:(d){final x=d.localPosition.dx,y=d.localPosition.dy;if(page==1){if(y<100&&x>590)toggleLocale();else if(y>570&&y<635&&x<720)setState((){persona=(x~/245).clamp(0,2);session.world.progress[0]!.persona=persona;});else if(y>570)setState(()=>page=0);else if(y>180&&y<290)setState((){persona=(x~/245).clamp(0,2);session.world.progress[0]!.persona=persona;});}else if(page==2){if(y>400&&y<500)restart();}else if(page==3){if(y>260&&y<470)chooseEvent((x~/380).clamp(0,1));}else if(page==4){if(y>390&&y<470&&x<365){Clipboard.setData(ClipboardData(text:snapshot().encode()));session.persist(page:page);}else if(y>390&&y<470)importSave();else if(y>520&&x<200)setState(()=>page=0);else if(y<100)setState(()=>page=0);}else if(y>500&&x>=590)next();else if(y>500&&x>=430)setState(()=>page=1);else if(y>500&&x>=260)setState(()=>page=4);else if(y>260&&y<470){final row=y<350?0:1,col=(x~/245).clamp(0,2),i=row==0?col:3+col;if(i<activities.length)select(i);}else if(y>500)next();},child:CustomPaint(key:ValueKey('$page-$week-$persona-$eventIndex${locale=='ko'?'':'-$locale'}'),painter:Scene(widget.story,week,coins,fatigue,selected,stats,bonds,milestones,lastResult,lastLine,page,persona,image,personaImage,history,eventIndex,snapshot().encode(),activities,collectionEntries),size:const Size(760,700))))));}
