void ending(Canvas c){final d=resolveEnding(JsonStoryAdapter(s),stats,bonds:bonds,milestones:milestones),rank=(d['rank'] as int?)??1;txt(c,'${JsonStoryAdapter(s).endingWeek}주의 끝',const Offset(24,28),32,ink,bold:true);txt(c,'루멘은 노아가 고른 방향을 기억합니다.',const Offset(25,70),14,teal);box(c,const Rect.fromLTWH(24,110,290,420),ink,radius:24);portrait(c,const Rect.fromLTWH(55,145,228,330),persona);txt(c,d['title'],const Offset(365,145),26,ink,bold:true);txt(c,d['body'],const Offset(365,200),16,ink);txt(c,'지혜 ${stats['지혜']}   공감 ${stats['공감']}   용기 ${stats['용기']}',const Offset(365,285),15,teal);txt(c,'은화 $coins · 피로 $fatigue · 목표 ${milestones.values.where((v)=>v).length}/${(s['milestones'] as List? ?? const []).length} · 유대 ${bonds.values.reduce((a,b)=>a+b)}',const Offset(365,320),15,ink);txt(c,'루멘 기록 등급 · ${List.filled(rank, '★').join()}',const Offset(365,350),15,teal,bold:true);if(d['epilogue']!=null)txt(c,d['epilogue'],const Offset(365,378),12,teal);box(c,const Rect.fromLTWH(365,410,300,64),sun,radius:18);txt(c,'다시 루멘으로',const Offset(450,432),17,ink,bold:true);drawLocalizedEnding(c,s,d,rank);}
@override bool shouldRepaint(Scene o)=>o.week!=week||o.selected!=selected||o.page!=page||o.persona!=persona||o.image!=image||o.eventIndex!=eventIndex||o.history.length!=history.length||o.saveCode!=saveCode||o.lastResult!=lastResult||o.lastLine!=lastLine||o.bonds.toString()!=bonds.toString()||o.collectionEntries.toString()!=collectionEntries.toString();}
